def gen(rng):
    import string
    codes_all = [a + b for a in string.ascii_uppercase for b in string.ascii_uppercase]

    def make(n, big, deficit_p):
        codes = rng.sample(codes_all, n)
        while True:
            hi = 10**9 - 100 if big else 60
            bal = []
            for _ in range(n):
                r = rng.random()
                if r < deficit_p:
                    bal.append(rng.randint(0, 99))
                elif r < deficit_p + 0.05:
                    bal.append(100)
                else:
                    bal.append(rng.randint(101, 100 + hi))
            if not any(b < 100 for b in bal) or not any(b > 100 for b in bal):
                continue
            total_def = sum(100 - b for b in bal if b < 100)
            total_sur = sum(b - 100 for b in bal if b > 100)
            if total_sur < total_def:
                # top up a random donor so the total is sufficient
                idx = [i for i, b in enumerate(bal) if b > 100]
                k = rng.choice(idx)
                bal[k] += total_def - total_sur
                if bal[k] > 10**9:
                    continue
            return str(n) + '\n' + '\n'.join('%s: %d' % (c, b) for c, b in zip(codes, bal))

    tests = [
        '5\nAU: 80\nUS: 140\nMX: 110\nSG: 120\nFR: 70',
        '2\nAA: 0\nBB: 100000',
        '2\nAA: 99\nBB: 101',
        '3\nXX: 100\nYY: 99\nZZ: 101',
        '4\nCA: 30\nDE: 90\nUK: 150\nIT: 170',
        '4\nAA: 300\nBB: 20\nCC: 20\nDD: 60',
    ]
    for n in (3, 4, 5, 6, 8, 10, 12):
        for _ in range(2):
            tests.append(make(n, False, rng.choice([0.3, 0.5, 0.7])))
    for n in (50, 200):
        tests.append(make(n, True, 0.5))
    tests.append(make(500, True, 0.5))
    tests.append(make(500, True, 0.9))
    tests.append(make(500, True, 0.1))
    codes = rng.sample(codes_all, 500)
    # one huge donor funds 499 deficit accounts
    lines = ['%s: %d' % (codes[0], 10**9)] + ['%s: %d' % (c, rng.randint(0, 99)) for c in codes[1:]]
    tests.append('500\n' + '\n'.join(lines))
    return tests

